try:
    print('>>> x = 3')
    print('>>> y = bytearray()')
    print('>>> x &= y')
    print('>>> x')
    x = 3
    y = bytearray()
    x &= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
